import kotlin.math.*
fun main() {
    println(sqrt(2.0)); println(exp(1.0)); println(ln(E)); println(tanh(0.5)); println(2.0.pow(10)); println(2.0.pow(0.5))
    println(PI); println(sin(PI / 6)); println(atan2(1.0, 1.0)); println(floor(-1.5)); println(ceil(1.2)); println(round(2.5)); println(round(3.5))
    println(abs(-3.0)); println(max(1.0, 2.0)); println(min(1.0, Double.NaN)); println(log10(1000.0)); println(log(8.0, 2.0)); println(2.7.roundToInt()); println((-1.0).sign); println(hypot(3.0, 4.0))
    println(sqrt(-1.0)); println(ln(0.0)); println(exp(710.0))
}
